import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Value-per-weight density of a candidate relative to the density of the remaining candidate pool."""
    k = len(values)
    if k == 0:
        return np.zeros(0)
    dens = values / np.maximum(weights, 1.0)
    pool_mean = np.mean(dens)
    pool_std = np.std(dens)
    denom = pool_std if pool_std > 1e-9 else 1.0
    z = (dens - pool_mean) / denom
    # squash
    return np.tanh(z)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Value-to-weight ratio of each candidate, normalised by the max ratio among candidates."""
    d = values / np.maximum(weights, 1)
    return d / (np.max(d) + 1e-9)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Value-to-weight density divided by sqrt(weight), normalised by its max."""
    d = (values / weights) / np.power(weights, 0.5)
    return d / (np.max(d) + 1e-9)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Fraction of the remaining capacity each candidate item would fill: weights / remaining."""
    return weights / (remaining + 1e-9)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Tight-capacity-gated weight-to-remaining ratio: (w / max(remaining,1)) when remaining < 20% of capacity, else 0."""
    rem = max(remaining, 1)
    tight = 1.0 if remaining < 0.2 * capacity else 0.0
    return tight * (weights / rem)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Rank of value minus rank of weight among candidates, scaled by fit slack (1 - w/remaining)."""
    k = len(values)
    if k == 1:
        return np.zeros(1)
    rv = np.argsort(np.argsort(values, kind="stable"), kind="stable") / (k - 1)
    rw = np.argsort(np.argsort(weights, kind="stable"), kind="stable") / (k - 1)
    fit = 1.0 - weights / max(remaining, 1)
    return np.clip((rv - rw) * (0.5 + 0.5 * fit), -1.0, 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Fill urgency (weight / remaining) times relative value (value / max value), clipped to [0, 1]."""
    rem = max(remaining, 1)
    vmax = float(np.max(values)) if values.size > 0 else 0.0
    if vmax <= 0.0:
        return np.zeros(values.shape, dtype=float)
    urgency = weights.astype(float) / float(rem)
    rel_value = values.astype(float) / vmax
    return np.clip(urgency * rel_value, 0.0, 1.0)
